from taf.internal.gnb.oam.coam.vdu.client.cm.v2 import (
    ApiClient,
    ClientType,
    CmApi,
    Configuration,
    ApiException
)

from taf.gnb.oam.coam.vdu.services.cm.http_client_v2 import CMv2HttpClient
from taf.gnb.oam.coam.vdu.utilities.logger import log_request_response
from taf.gnb.oam.coam.vdu.utilities.poll_status import poll_status
from taf.gnb.oam.coam.vdu.utilities.token_provider import auto_token_refresh
from taf.gnb.oam.coam.vdu.utilities.token_storage import TokenStorage
from taf.gnb.oam.coam.vdu.services.sec.sec_v1 import SECv1
from taf.gnb.oam.coam.vdu.services.sec.sec_licensed_v1 import SECLicensedv1
from taf.gnb.oam.coam.vdu.utilities.file_operations import save_to_file


@auto_token_refresh(api_exception=ApiException)
class CMv2:
    def __init__(self, con_details):
        self.con_details = con_details
        self.token_storage = TokenStorage(connection_name=con_details.alias)
        self.sec = SECLicensedv1.get_instance(connection_name=con_details.alias) \
            if con_details.use_m2m else SECv1.get_instance(connection_name=con_details.alias)

        conf = Configuration()
        conf.verify_ssl = False
        conf.host = con_details.get_api_client_configuration(original_endpoint=conf.host)
        self.configuration = conf

        api_client = ApiClient(configuration=conf)
        api_client.request = log_request_response(api_client.request)

        self._cm_api_v2 = CmApi(api_client)
        client_type = ClientType()
        self.accepted_client_types = {'em': client_type.EM,
                                      'nms': client_type.NMS,
                                      'internal': client_type.INTERNAL}
        self.local_client = CMv2HttpClient(base_url=con_details.base_url,
                                           connection_alias=con_details.alias)

    def _get_current_plan_id(self, timeout=None):
        response = self._cm_api_v2.get_plan_ids(status='activated', _request_timeout=timeout)
        return response[0].user_plan_id

    def get_current_plan_objects(self, class_name=None, ancestor_dist_name=None, dist_names=None, timeout=30):
        if isinstance(class_name, str):
            class_name = [class_name]
        return self.local_client.get_current_plan_objects(class_name=class_name, ancestor_dist_name=ancestor_dist_name,
                                                          dist_names=dist_names, timeout=timeout)

    def activate_pre_activated_plan(self, plan_id, timeout=30):
        x_oam_client_type = self.accepted_client_types['em']
        activated_res = self._cm_api_v2.start_activation(x_oam_client_type=x_oam_client_type,
                                                         plan_id=plan_id,
                                                         _request_timeout=timeout)
        return activated_res.id

    def get_activated_operation_status(self, plan_id, operation_id, timeout=30):
        res = self.local_client.get_activated_operation_status(plan_id=plan_id, operation_id=operation_id, timeout=timeout)
        return res["isCompleted"]

    def get_activated_operation_detail_status(self, plan_id, operation_id, timeout=30):
        return self.local_client.get_activated_operation_detail_status(plan_id=plan_id, operation_id=operation_id,
                                                                       timeout=timeout)

    def get_current_plan_content(self, include_runtime_data=False, include_auto_config_data=True, timeout=30):
        operation = self.local_client.download_current_plan(x_oam_client_type='em',
                                                            include_runtime_data=include_runtime_data,
                                                            include_auto_configured_data=include_auto_config_data,
                                                            timeout=timeout)
        poll_status(instance=self.local_client,
                    method_name="get_download_plan_operation_status",
                    just_id=operation['id'],
                    timeout=timeout)

        return self.local_client.get_downloaded_plan_file(just_id=operation['id'])

    def download_current_plan(self, include_runtime_data=False, timeout=30, include_auto_config_data=True):
        return self.local_client.download_current_plan(x_oam_client_type='em',
                                                       include_runtime_data=include_runtime_data,
                                                       include_auto_configured_data=include_auto_config_data,
                                                       timeout=timeout)

    def get_download_plan_operation_status(self, operation_id, timeout=30):
        return self.local_client.get_download_plan_operation_status(just_id=operation_id,
                                                                    timeout=timeout)

    def get_downloaded_plan_file(self, operation_id, path, timeout=30):
        plan_content = self.local_client.get_downloaded_plan_file(just_id=operation_id, timeout=timeout)
        save_to_file(target_path=path, content=plan_content)
